Method.Implementation:
If '$IsObject(pOptions) { Set pOptions = {} }
Set tResult = {}
Set tResult."title" = ..%StrOrNull(pOptions.title)
Set tResult."subtitle" = ..%StrOrNull(pOptions.subtitle)
Set tResult."cube" = ..%StrOrNull(pOptions.cube)
If (pOptions.filters = "") {
    Set tResult.filters = []
} Else {
    Set tResult.filters = pOptions.filters
}
Set tRowCaptions = ..%ParseCaptions(pOptions.%Get("rowCaptions"))

Set tRS = ##class(%DeepSee.ResultSet).%New()
Set tSC = tRS.%PrepareMDX(pMDX)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

Set tListingName = pOptions.%Get("listing", "")
If (tListingName '= "") {
    Set tSC = tRS.%SetListing(tListingName)
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)
}
Set tRS.%Query.%MaxListingRows = 0

Set tSC = tRS.%ExecuteAsynch(,,1)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

If tRS.%IsDrillThrough() {
    Set tResult.kind = "listing"
    Do ..%BuildListing(tRS, tResult)
} Else {
    Set tResult.kind = "cellset"
    Set tRowTotals = $Select($IsObject(pOptions):(pOptions.rowTotals=1),1:0)
    Set tColTotals = $Select($IsObject(pOptions):(pOptions.columnTotals=1),1:0)
    Set tRowTotalAgg = $Select($IsObject(pOptions)&&(pOptions.%Get("rowTotalAgg","")'=""):pOptions.rowTotalAgg,1:"sum")
    Set tColTotalAgg = $Select($IsObject(pOptions)&&(pOptions.%Get("columnTotalAgg","")'=""):pOptions.columnTotalAgg,1:"sum")
    Do ..%BuildCellset(tRS, tResult, tRowTotals, tColTotals, tRowTotalAgg, tColTotalAgg)

    Set tRowHeaderNames = []
    For n=1:1:tResult.rowHeaderDepth {
        Do tRowHeaderNames.%Push($Select(n<=tRowCaptions.Count():tRowCaptions.GetAt(n),1:""))
    }
    Set tResult.rowHeaderNames = tRowHeaderNames
}

Quit tResult

Set tList = ##class(%ListOfDataTypes).%New()
If $IsObject($Get(pValue)) {
    For i=0:1:pValue.%Size()-1 { Do tList.Insert(pValue.%Get(i)) }
} ElseIf ($Get(pValue) '= "") {
    For i=1:1:$Length(pValue,$C(10)) { Do tList.Insert($Piece(pValue,$C(10),i)) }
}
Quit tList

Set tSC = pRS.%GetListingResultSet(.tListingRS, .tListingFields)
If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)

Set tColumnMeta = tListingRS.%GetMetaData().columns
Set tColumns = []
If (tListingFields = "") {
    Set tColCount = tColumnMeta.Count()
    For c=1:1:tColCount {
        Set tInfo = tColumnMeta.GetAt(c)
        Set tNumeric = $Case(tInfo.ODBCType, 2:1, 4:1, 8:1, :0)
        Do tColumns.%Push({"name": (tInfo.colName), "numeric": (tNumeric)})
    }
} Else {
    Set tColCount = $ListLength(tListingFields)
    For c=1:1:tColCount {
        Do tColumns.%Push({"name": ($ListGet(tListingFields,c)), "numeric": 0})
    }
}
Set pResult.columns = tColumns

Set tRows = []
While tListingRS.%Next(.tSC) {
    If $$$ISERR(tSC) Throw ##class(%Exception.StatusException).CreateFromStatus(tSC)
    Set tRow = []
    For c=1:1:tColCount {
        If (tListingFields = "") {
            Set tValue = tListingRS.%GetData(c)
        } Else {
            Set tValue = tListingRS.%Get($ListGet(tListingFields,c))
        }
        Do tRow.%Push(tValue)
    }
    Do tRows.%Push(tRow)
}
Set pResult.rows = tRows

Set tAxisCount = pRS.%GetAxisCount()

// Single-value answer (no axes) - report it as a 1x1 table.
If (tAxisCount = 0) {
    Set tValue = pRS.%GetValue()
    Set pResult.colHeaderDepth = 1
    Set pResult.rowHeaderDepth = 1
    Set pResult.colCount = 1
    Set pResult.rowCount = 1
    Set pResult.columnHeaders = [["All"]]
    Set pResult.rowHeaders = [["Count"]]
    Set tCell = ..%MakeNumericCell(tValue, "")
    Set tRowArr = []
    Do tRowArr.%Push(tCell)
    Set tData = []
    Do tData.%Push(tRowArr)
    Set pResult.cells = tData
    Quit
}

For a=1:1:tAxisCount { Set tAxisSize(a) = pRS.%GetAxisSize(a) }
Set tColCount = +$Get(tAxisSize(1))
Set tHasRows = (tAxisCount >= 2)
Set tRowCount = $Select(tHasRows:+$Get(tAxisSize(2)),1:1)

If (tColCount = 0) || (tRowCount = 0) {
    Set pResult.colHeaderDepth = 0
    Set pResult.rowHeaderDepth = 0
    Set pResult.colCount = 0
    Set pResult.rowCount = 0
    Set pResult.columnHeaders = []
    Set pResult.rowHeaders = []
    Set pResult.cells = []
    Quit
}

// First pass: column headers + per-column format/solve order.
Set tColHeaderDepth = 1
For c=1:1:tColCount {
    Kill tNames
    Set tCount = pRS.%GetOrdinalLabel(.tNames,1,c,.tFormat,.tSolveOrder)
    Set:(tCount>tColHeaderDepth) tColHeaderDepth = tCount
    Set tColFormat(c) = tFormat
    Set tColSolveOrder(c) = tSolveOrder
    For n=1:1:tCount { Set tColLabel(c,n) = $Get(tNames(n)) }
}

// Second pass: row headers + per-row format/solve order.
Set tRowHeaderDepth = 1
If (tHasRows) {
    For r=1:1:tRowCount {
        Kill tLabels
        Set tCount = pRS.%GetOrdinalLabel(.tLabels,2,r,.tFormat,.tSolveOrder)
        Set:(tCount>tRowHeaderDepth) tRowHeaderDepth = tCount
        Set tRowFormat(r) = tFormat
        Set tRowSolveOrder(r) = tSolveOrder
        For n=1:1:tCount { Set tRowLabel(r,n) = $Get(tLabels(n)) }
    }
} Else {
    Set tRowFormat(1) = ""
    Set tRowSolveOrder(1) = 0
    Set tRowLabel(1,1) = "Results"
}

Set tDefaultFormat = pRS.%GetDefaultFormat()
Set tHasOverride = pRS.%HasCellFormatOverride()

// Column headers, outermost (depth tColHeaderDepth) first, innermost (1) last - top-to-bottom.
// Pushed with explicit type "string" - member captions that happen to look numeric
// (e.g. a Year value "2024", or a flag member "0"/"1") would otherwise get
// auto-detected as JSON numbers, producing a mixed string/number array that crashes
// XLSXWriter's header-flattening join for any pivot with a ragged/asymmetric column axis.
Set tColumnHeaders = []
For lvl=tColHeaderDepth:-1:1 {
    Set tRowOfHeaders = []
    For c=1:1:tColCount {
        Do tRowOfHeaders.%Push($Get(tColLabel(c,lvl)),"string")
    }
    Do tColumnHeaders.%Push(tRowOfHeaders)
}
Set pResult.columnHeaders = tColumnHeaders

// Row headers, outermost (depth) first, innermost (1) last - left-to-right per row.
Set tRowHeaders = []
For r=1:1:tRowCount {
    Set tHeaderRow = []
    For lvl=tRowHeaderDepth:-1:1 {
        Do tHeaderRow.%Push($Get(tRowLabel(r,lvl)),"string")
    }
    Do tRowHeaders.%Push(tHeaderRow)
}
Set pResult.rowHeaders = tRowHeaders

Set pResult.colHeaderDepth = tColHeaderDepth
Set pResult.rowHeaderDepth = tRowHeaderDepth
Set pResult.colCount = tColCount
Set pResult.rowCount = tRowCount

// Data cells.
Set tData = []
For r=1:1:tRowCount {
    Set tRowArr = []
    For c=1:1:tColCount {
        Set tValue = $Case(tAxisCount, 1:pRS.%GetOrdinalValue(c), :pRS.%GetOrdinalValue(c,r))

        If (+$Get(tColSolveOrder(c)) >= +$Get(tRowSolveOrder(r))) {
            Set tFormat = $Select($Get(tColFormat(c))'="":tColFormat(c), $Get(tRowFormat(r))'="":tRowFormat(r), 1:tDefaultFormat)
        } Else {
            Set tFormat = $Select($Get(tRowFormat(r))'="":tRowFormat(r), $Get(tColFormat(c))'="":tColFormat(c), 1:tDefaultFormat)
        }
        If ((tAxisCount>1) && tHasOverride) {
            Set tFO = pRS.%GetCellFormatOverride(c,r)
            Set:tFO'="" tFormat = tFO
        }

        Do tRowArr.%Push(..%MakeCell(tValue, tFormat))
    }
    Do tData.%Push(tRowArr)
}
Set pResult.cells = tData

If ('pRowTotals) && ('pColTotals) Quit

// Column totals: one value per column, summed down the rows - rendered as a "Total" row.
// "pct" (% of Total) returns a raw 0-1 fraction, not a value in the column's own
// units, so it needs its own percent format rather than the column's normal one.
If (pColTotals) {
    Set tColTotals = []
    Set tColPct = (pColTotalAgg="pct")
    For c=1:1:tColCount {
        Set tFormat = $Select(tColPct:"0.00%",$Get(tColFormat(c))'="":tColFormat(c),1:tDefaultFormat)
        Do tColTotals.%Push(..%MakeCell(pRS.%GetColumnTotal(c,pColTotalAgg),tFormat))
    }
    Set pResult.columnTotals = tColTotals
    Set pResult.columnTotalAgg = pColTotalAgg
}

// Row totals: one value per row, summed across columns - rendered as a "Total" column.
// Grand total is only meaningful (and only used by the writer) alongside row totals.
If (pRowTotals) {
    Set tRowTotals = []
    Set tGrandTotal = 0
    Set tRowPct = (pRowTotalAgg="pct")
    For r=1:1:tRowCount {
        Set tFormat = $Select(tRowPct:"0.00%",$Get(tRowFormat(r))'="":tRowFormat(r),1:tDefaultFormat)
        Set tSum = pRS.%GetRowTotal(r,pRowTotalAgg)
        Set tGrandTotal = tGrandTotal + tSum
        Do tRowTotals.%Push(..%MakeCell(tSum,tFormat))
    }
    Set pResult.rowTotals = tRowTotals
    Set pResult.rowTotalAgg = pRowTotalAgg
    Set pResult.grandTotal = ..%MakeCell(tGrandTotal,$Select(tRowPct:"0.00%",1:tDefaultFormat))
}

If (pFormat = "%string%") {
    Quit {"t":"s","v":(pValue),"fmt":"@"}
}
ElseIf (pFormat = "%date%") {
    If (pValue = "") {
        Quit {"t":"s","v":""}
    }
    Set tISO = $ZDT(pValue\1,3)
    Quit {"t":"d","v":(tISO),"fmt":"mm/dd/yyyy"}
}
ElseIf (pFormat = "%time%") {
    Quit {"t":"t","v":(+pValue),"fmt":"[h]:mm:ss"}
}
Else {
    Quit ..%MakeNumericCell(pValue, pFormat)
}

If $IsValidNum(pValue) {
    Quit {"t":"n","v":(+pValue),"fmt":(..%TranslateFormat(pFormat))}
}
Quit {"t":"s","v":(pValue),"fmt":"@"}

Set tSC = $$$OK
Try {
    Set tBytes = ..BuildTiny()
    Set tStream = ##class(%Stream.FileBinary).%New()
    Set tSC = tStream.LinkToFile(pFile)
    If $$$ISERR(tSC) Quit
    Do tStream.Write(tBytes)
    Set tSC = tStream.%Save()
}
Catch ex {
    Set tSC = ex.AsStatus()
}
Quit tSC

try {
    var menus = document.querySelectorAll('.dsptIconDropdownMenu');
    for (var i = 0; i < menus.length; i++) {
        var menu = menus[i];
        if (menu.getAttribute('data-extraExportAdded')) { continue; }

        var links = menu.getElementsByTagName('a');
        var excelLink = null;
        for (var j = 0; j < links.length; j++) {
            var onclickAttr = links[j].getAttribute('onclick') || '';
            if (onclickAttr.indexOf('exportExcel') >= 0) {
                excelLink = links[j];
                break;
            }
        }
        if (!excelLink) { continue; }

        var match = (excelLink.getAttribute('onclick') || '').match(/toggleExportMenu\('([^']+)'\)/);
        var menuId = match ? match[1] : '';

        var xlsxLink = document.createElement('a');
        xlsxLink.setAttribute('title', 'Microsoft Excel Workbook (.xlsx)');
        xlsxLink.setAttribute('onclick', "zenPage.toggleExportMenu('" + menuId + "');zenPage.exportXLSX();");
        xlsxLink.textContent = 'Excel Workbook';
        excelLink.parentNode.insertBefore(xlsxLink, excelLink.nextSibling);

        var jsonLink = document.createElement('a');
        jsonLink.setAttribute('title', 'JSON (.json)');
        jsonLink.setAttribute('onclick', "zenPage.toggleExportMenu('" + menuId + "');zenPage.exportJSON();");
        jsonLink.textContent = 'JSON';
        xlsxLink.parentNode.insertBefore(jsonLink, xlsxLink.nextSibling);

        menu.setAttribute('data-extraExportAdded', '1');
    }
}
catch (e) {
    // Non-fatal: if the stock page's DOM structure ever changes enough that this
    // stops finding the menu, just skip adding the options rather than break the page.
}

var table = this.getPivot();
if (!table || ('' == table.cubeName) || ('' == table.queryKey)) {
    return '';
}

var mdx = table.GetCurrentQueryText("export");
var nonce = '';
if (mdx.toString().length > 1000) {
    // avoid long urls for IE!
    nonce = this.CreateQueryNonce(mdx);
    if (nonce.toString().indexOf('ERROR:') >= 0) {
        alert(nonce);
        return '';
    }
}

var url;
if (nonce) {
    url = pPage + '?NONCE=' + encodeURIComponent(nonce);
}
else {
    url = pPage + '?MDX=' + encodeURIComponent(mdx);
}

var title = table.printTitle;
var subtitle = table.printSubtitle;
if (title == '') {
    title = this.pivotName;
    if (title != '') {
        var s = title.toString().split('.');
        s.length = s.length - 1;
        title = s.join('.');
    }
}
// Strip any BI-folder path prefix ("Test/Crossjoin...") - that's portal
// organization, not part of the report's identity, and shouldn't leak into
// the filename or the Info sheet's title.
if (title.indexOf('/') >= 0) {
    var pathParts = title.split('/');
    title = pathParts[pathParts.length - 1];
}
url += '&TITLE=' + encodeURIComponent(title);
url += '&SUBTITLE=' + encodeURIComponent(subtitle);
url += '&CUBE=' + encodeURIComponent(table.cubeName || '');
if (table.listing != '') {
    url += '&LISTINGNAME=' + encodeURIComponent(table.listing);
}
// table.rowTotals/table.columnTotals are independent pivot options - a pivot can
// have either, both, or neither. These must stay separate params: OR-ing them into
// one combined flag made the export always render BOTH totals whenever ONE was
// enabled, adding an unrequested "Total" column/row that often summed unrelated
// measures together.
//
// The widget's own property names are the OPPOSITE of what they render: checking
// "Row Options -> Summary" sets table.rowTotals=true (and table.rowTotalAgg to the
// aggregation dropdown next to it) but renders an extra Totals ROW (confirmed live -
// Pivot Options dialog, control_21), and "Column Options -> Summary"
// (table.columnTotals/table.columnTotalAgg) renders an extra Totals COLUMN.
// ROWTOTALS/COLUMNTOTALS on our own REST API mean what they say (see MDXExport.cls's
// doc comment: ROWTOTALS = "Total" column, COLUMNTOTALS = "Total" row), so the
// mapping below - flags AND their aggregation functions - is deliberately crossed to
// match what actually renders in the Analyzer, not the widget's own (misleading)
// property names. table.rowTotalAgg/table.columnTotalAgg values ("sum", "count",
// "min", "max", "avg", "pct") pass straight through with no translation - they're
// exactly what MDXExport.cls's rowTotalAgg/columnTotalAgg options (and
// %DeepSee.ResultSet's own %GetRowTotal/%GetColumnTotal) expect.
if (table.rowTotals) {
    url += '&COLUMNTOTALS=1';
    if (table.rowTotalAgg) {
        url += '&COLUMNTOTALAGG=' + encodeURIComponent(table.rowTotalAgg);
    }
}
if (table.columnTotals) {
    url += '&ROWTOTALS=1';
    if (table.columnTotalAgg) {
        url += '&ROWTOTALAGG=' + encodeURIComponent(table.columnTotalAgg);
    }
}
// Row axis dimension/level captions (e.g. "YearSold","Product Category") - the
// ResultSet API has no way to derive these; the pivot table widget already has
// them client-side. Same source stock exportExcel() uses for its ROWCAPTIONS param.
url += '&ROWCAPTIONS=' + encodeURIComponent(table.getRowCaptions().join('\n'));

// The pivot's active filter selections (e.g. Product Category = Cereal+Dairy+...)
// for the Info sheet's recap block - same table.getFilterInfo() call stock
// exportExcel() uses for its FILTERNAMES/FILTERVALUES params.
var filterNames = [];
var filterValues = [];
table.getFilterInfo(filterNames, filterValues);
if (filterNames.length > 0) {
    url += '&FILTERNAMES=' + encodeURIComponent(filterNames.join('\n'));
    url += '&FILTERVALUES=' + encodeURIComponent(filterValues.join('\n'));
}

var fileBase;
if (title) {
    fileBase = title;
}
else {
    // Ad-hoc pivot built in the Analyzer and never saved - no name to hang a
    // filename on. Fall back to the cube plus a short timestamp instead of a
    // bare "export.xlsx" that every such download would collide on.
    var now = new Date();
    var pad = function(n) { return (n < 10 ? '0' : '') + n; };
    var ts = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
    fileBase = (table.cubeName ? table.cubeName : 'export') + '_' + ts;
}
url += '&FILENAME=' + encodeURIComponent(fileBase + '.' + pExtension);

return zenLink(url);

Set tSC = $$$OK
Try {
    Set tNonce = $Get(%request.Data("NONCE",1))
    If (tNonce '= "") {
        Set tMDX = $Get($$$DeepSeeQueryNonceGLVN(tNonce))
        Kill $$$DeepSeeQueryNonceGLVN(tNonce)
    } Else {
        Set tMDX = $Get(%request.Data("MDX",1))
    }
    If (tMDX = "") {
        Set %response.Status = "400 Bad Request"
        Quit
    }

    Set tOptions = {}
    Set tOptions.title = $Get(%request.Data("TITLE",1))
    Set tOptions.subtitle = $Get(%request.Data("SUBTITLE",1))
    Set tOptions.cube = $Get(%request.Data("CUBE",1))
    Set tOptions.listing = $Get(%request.Data("LISTINGNAME",1))
    Set tOptions.rowTotals = ($Get(%request.Data("ROWTOTALS",1)) = "1")
    Set tOptions.columnTotals = ($Get(%request.Data("COLUMNTOTALS",1)) = "1")
    Set tOptions.rowTotalAgg = $Get(%request.Data("ROWTOTALAGG",1))
    Set tOptions.columnTotalAgg = $Get(%request.Data("COLUMNTOTALAGG",1))
    Set tOptions.rowCaptions = $Get(%request.Data("ROWCAPTIONS",1))
    Set tOptions.filters = ##class(BIExport.MDXExport).%ParseFilterPairs($Get(%request.Data("FILTERNAMES",1)), $Get(%request.Data("FILTERVALUES",1)))

    Set tData = ##class(BIExport.MDXExport).BuildExportData(tMDX, tOptions)

    Do tData.%ToJSON()
}
Catch ex {
    Set %response.Status = "500 Internal Server Error"
    Write ex.DisplayString()
}
Quit $$$OK

Set tSC = $$$OK
Try {
    Set tNonce = $Get(%request.Data("NONCE",1))
    If (tNonce '= "") {
        Set tMDX = $Get($$$DeepSeeQueryNonceGLVN(tNonce))
        Kill $$$DeepSeeQueryNonceGLVN(tNonce)
    } Else {
        Set tMDX = $Get(%request.Data("MDX",1))
    }
    If (tMDX = "") {
        Set %response.Status = "400 Bad Request"
        Quit
    }

    Set tOptions = {}
    Set tOptions.title = $Get(%request.Data("TITLE",1))
    Set tOptions.subtitle = $Get(%request.Data("SUBTITLE",1))
    Set tOptions.cube = $Get(%request.Data("CUBE",1))
    Set tOptions.listing = $Get(%request.Data("LISTINGNAME",1))
    Set tOptions.rowTotals = ($Get(%request.Data("ROWTOTALS",1)) = "1")
    Set tOptions.columnTotals = ($Get(%request.Data("COLUMNTOTALS",1)) = "1")
    Set tOptions.rowTotalAgg = $Get(%request.Data("ROWTOTALAGG",1))
    Set tOptions.columnTotalAgg = $Get(%request.Data("COLUMNTOTALAGG",1))
    Set tOptions.rowCaptions = $Get(%request.Data("ROWCAPTIONS",1))
    Set tOptions.filters = ##class(BIExport.MDXExport).%ParseFilterPairs($Get(%request.Data("FILTERNAMES",1)), $Get(%request.Data("FILTERVALUES",1)))

    Set tData = ##class(BIExport.MDXExport).BuildExportData(tMDX, tOptions)
    Set tBytes = ##class(BIExport.XLSXWriter).BuildXLSX(tData.%ToJSON())

    Set tStream = ##class(%Stream.TmpBinary).%New()
    Do tStream.Write(tBytes)
    Do tStream.Rewind()
    Do tStream.OutputToDevice()
}
Catch ex {
    Set %response.Status = "500 Internal Server Error"
    Write ex.DisplayString()
}
Quit $$$OK
